import ast,json,pathlib,subprocess,hashlib,importlib.util,itertools,random
root=pathlib.Path('/workspace'); p=json.loads((root/'proposal.json').read_text())
r=json.loads(subprocess.check_output(['python3',str(root/'tools.py'),'resolve','run://r-001'],text=True))
def validate(v,s,path='"'$'"'):
 t=s.get('type')
 if t=='object':
  assert isinstance(v,dict),path
  assert all(k in v for k in s.get('required',[])),path
  if s.get('additionalProperties') is False: assert set(v)<=set(s.get('properties',{})),path
  for k,x in v.items():
   if k in s.get('properties',{}): validate(x,s['properties'][k],path+'.'+k)
 elif t=='array':
  assert isinstance(v,list) and len(v)>=s.get('minItems',0),path
  for i,x in enumerate(v): validate(x,s.get('items',{}),path+f'[{i}]')
 elif t=='string': assert isinstance(v,str) and len(v)>=s.get('minLength',0),path
 if 'const' in s: assert v==s['const'],path
 if 'enum' in s: assert v in s['enum'],path
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert len(p['variants'])==4 and sum(v['role']=='candidate' for v in p['variants'])==1
assert len({v['name'] for v in p['variants']})==4 and len({v['file'] for v in p['variants']})==4
old=ast.parse((root/'history_r0026_ordered_switch.py').read_text());oc=next(n for n in old.body if isinstance(n,ast.ClassDef));om={n.name:n for n in oc.body if isinstance(n,ast.FunctionDef)}
dump=lambda n:ast.dump(n,include_attributes=False)
results=[];asts=[]
for v in p['variants']:
 assert pathlib.Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 source=(root/v['file']).read_text();tree=ast.parse(source);compile(tree,v['file'],'exec')
 node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets));assert ast.literal_eval(node.value)==v['config']
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef));m={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 unchanged=[]
 for name,fn in om.items():
  if name not in ('__init__','_switch_statistics','_all_features','diagnostics'):
   assert dump(m[name])==dump(fn),name;unchanged.append(name)
 assert [dump(n) for n in m['__init__'].body[:len(om['__init__'].body)]]==[dump(n) for n in om['__init__'].body]
 renamed=ast.parse(ast.unparse(m['_switch_all_features'])).body[0];renamed.name='_all_features';assert dump(renamed)==dump(om['_all_features'])
 grouping=ast.parse(ast.unparse(m['_switch_statistics'])).body[0]
 grouping.body=[n for n in grouping.body if not (isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Tuple) and [getattr(x,'id',None) for x in n.targets[0].elts]==['newest','oldest'])]
 loop=next(n for n in grouping.body if isinstance(n,ast.For));start=next(i for i,n in enumerate(loop.body) if isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name) and n.targets[0].id=='group_count')
 # Five new statements, not six. The initial audit removed one old statement.
 loop.body[start:start+5]=[];ret=grouping.body[-1].value
 assert [k.value for k in ret.keys][-2:]==['newest','oldest'];ret.keys=ret.keys[:-2];ret.values=ret.values[:-2]
 assert dump(grouping)==dump(om['_switch_statistics'])
 allowed={'math','torch','numpy','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(x.name.split('.')[0] in allowed for x in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in ('open','exec','eval','__import__','compile')
  if isinstance(n,ast.Subscript) and isinstance(n.value,ast.Name) and n.value.id=='batch' and isinstance(n.slice,ast.Constant): assert n.slice.value in {'static','history_category','history_brand','history_type','history_age_seconds','history_mask'}
 results.append({'file':v['file'],'sha256':hashlib.sha256(source.encode()).hexdigest(),'preserved_helpers':len(unchanged),'constructor_prefix_nodes':len(om['__init__'].body)})
 node.value=ast.Constant(None);asts.append(dump(tree))
